from math import comb
# Exact Laurent polynomials in c,q,s with q"'^2=1-c''^2 and integral coefficients.
# Keys give (power of c, power of q in {0,1}, integer power of s).
def norm(p):
    out={}
    for (i,j,k),v in p.items():
        m,b=divmod(j,2)
        for t in range(m+1):
            key=(i+2*t,b,k)
            out[key]=out.get(key,0)+v*comb(m,t)*(-1)**t
    return {key:v for key,v in out.items() if v}
def add(*ps):
    out={}
    for p in ps:
        for key,v in p.items(): out[key]=out.get(key,0)+v
    return norm(out)
def scale(p,v): return {key:a*v for key,a in p.items() if a*v}
def sub(p,q): return add(p,scale(q,-1))
def mul(p,q):
    out={}
    for a,v in p.items():
        for b,w in q.items():
            key=tuple(x+y for x,y in zip(a,b))
            out[key]=out.get(key,0)+v*w
    return norm(out)
def mm(A,B):
    return [[add(*(mul(A[i][k],B[k][j]) for k in range(2))) for j in range(2)] for i in range(2)]
def ms(A,p): return [[mul(v,p) for v in row] for row in A]
Z={}; I1={(0,0,0):1}; c={(1,0,0):1}; q={(0,1,0):1}; s={(0,0,1):1}; r={(0,0,-1):1}
I=[[I1,Z],[Z,I1]]
c2=mul(c,c); q2=mul(q,q); cq=mul(c,q)
h=add(s,r); K=add(h,scale(I1,2)); twice_z=sub(mul(K,c2),h)
E=[[c,q],[scale(q,-1),c]]
C=[[sub(c2,mul(r,q2)),mul(add(I1,r),cq)], [scale(mul(add(I1,s),cq),-1),sub(c2,mul(s,q2))]]
checks={}
checks['"'det C = 1']=sub(mul(C[0][0],C[1][1]),mul(C[0][1],C[1][0]))==I1
checks['tr C = K c"'^2-h'"']=add(C[0][0],C[1][1])==twice_z
checks['(EC)12 = q(2z+r)']=mm(E,C)[0][1]==mul(q,add(twice_z,r))
C2=mm(C,C); zC=ms(C,twice_z)
checks['C"'^2-2z C+I=0'"']=all(not add(C2[i][j],scale(zC[i][j],-1),I[i][j]) for i in range(2) for j in range(2))
checks['h-2=(s-1)"'^2/s'"']=sub(h,scale(I1,2))==mul(mul(sub(s,I1),sub(s,I1)),r)
checks['K=(s+1)"'^2/s'"']=K==mul(mul(add(s,I1),add(s,I1)),r)
# Finite direct-power comparisons corroborate, but do not prove, the uniform induction.
P0=I1; P1=add(twice_z,r); Cpow=I
for n in range(7):
    if n==0: P=P0
    elif n==1: P=P1
    else:
        P=sub(mul(twice_z,P1),P0)
        P0,P1=P1,P
    checks[f'direct-power identity n={n}']=mm(E,Cpow)[0][1]==mul(q,P)
    Cpow=mm(Cpow,C)
for name,ok in checks.items(): print(f'{name}: {\"PASS\" if ok else \"FAIL\"}')
assert all(checks.values())
print('All arithmetic exact. Root count and simplicity require the separately audited uniform argument.')
